import React from 'react';
import Card from './TitleDescCard';
import './HorizontalGallery.css';


const Gallery = () => {
  const projects = [
    {
      title: 'Co-Pilot Research Assistant | VCL- NOVA | Vancouver, BC | May 2026– Current',
      description: ' Analyzed 500+ participants’ data using Jupyter/Python; Interpreted 20+ metrics for inattentional blindness under 5+ conditions. Created conditions using GIMP to support ongoing cognitive vision research; and performed literature review and process documentation. Supported cross-project lab initiatives, met milestone check-ins with supervising PL, and collaborated with lab members. ',
    },
    {
      title: 'Freelance Website Developer ',
      description: 'Designed and shipped responsive sites. Delivered complete website solutions for Adventure Osteopathy and Universal Voices non-profit.', 
    },
    {
      title: 'Coding Instructor | Code Ninjas',
      description: 'Taught 100+ students coding fundamentals and DSA through game-based projects; improving retention by 16%.', 
    },
    
    // Add more projects here
  ];

  return (
    <div className="galleryContainer"> 
        <div className="gallery">
        {projects.map((project, index) => (
            <Card
            key={index}
            title={project.title}
            description={project.description}
            imageUrl={project.imageUrl}
            projectLink={project.projectLink}
            githubLink={project.githubLink}
            />
        ))}
        </div>
    </div>
  );
};

export default Gallery;
